**Passo 1 — instale o morgan:**

```bash
npm install morgan
```

**Passo 2 — servidor com morgan + log estruturado** (server.mjs):

```js
import express from 'express';
import morgan from 'morgan';

const app = express();
app.use(morgan(':method :url :status :response-time ms')); // 1 linha por requisição

// imprime UMA linha de JSON (fácil de buscar depois)
function registrarLog(level, msg, extras = {}) {
  console.log(JSON.stringify({
    level,
    msg,
    timestamp: new Date().toISOString(),
    ...extras,
  }));
}

app.get('/health', (req, res) => {
  registrarLog('info', 'health check', { status: 200 });
  res.status(200).json({ status: 'ok' });
});

// rota que pode quebrar — para ver o 500 no log
app.get('/divide/:numero', (req, res) => {
  const numero = Number(req.params.numero);
  if (numero === 0) {
    registrarLog('error', 'divisão por zero', { rota: req.originalUrl, status: 500 });
    return res.status(500).json({ erro: 'não divido por zero' });
  }
  registrarLog('info', 'divisão ok', { numero, resultado: 10 / numero });
  res.json({ resultado: 10 / numero });
});

const porta = process.env.PORT ?? 3000;
app.listen(porta, () => registrarLog('info', 'servidor subiu', { porta }));
```

**Passo 3 — o que monitorar (a lista curta):**

1. **Erros 5xx** — se o número sobe, algo quebrou: procure no log as linhas com "level":"error".
2. **Erros 4xx** — volume alto pode ser cliente quebrado ou ataque; é aviso, não pânico.
3. **Tempo de resposta** — o `:response-time ms` do morgan mostra requisições lentas antes de virarem reclamação.
4. **Health check** — monitorar o `/health` de fora avisa quando o servidor caiu, mesmo que ninguém tenha visto o erro.

Acessando `/divide/0` com o servidor rodando, o log mostra a linha do morgan com status 500 e a linha estruturada `level: "error"` — exatamente o que você precisa para descobrir o problema de onde estiver, sem abrir o código.
